import{_ as e,o as a,c as r,a3 as o}from"./chunks/framework.BM_-pWjS.js";const p=JSON.parse('{"title":"Rating photos","description":"","frontmatter":{},"headers":[],"relativePath":"en/rating.md","filePath":"en/rating.md"}'),d={name:"en/rating.md"};function i(n,t,s,h,c,l){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="rating-photos" tabindex="-1">Rating photos <a class="header-anchor" href="#rating-photos" aria-label="Permalink to &quot;Rating photos&quot;">​</a></h1><p>Rating and label data is written in <strong>XMP format</strong>. For JPEG files, XMP is embedded directly in the file by default. For RAW files, a sidecar file (<code>.xmp</code>) is always used. JPEG files can be switched to sidecar mode in Settings. Ratings are fully compatible with Lightroom, Capture One, and Adobe Bridge.</p><h2 id="star-ratings" tabindex="-1">Star ratings <a class="header-anchor" href="#star-ratings" aria-label="Permalink to &quot;Star ratings&quot;">​</a></h2><p>Star ratings can be applied via <strong>keyboard shortcut</strong> or <strong>right-click menu</strong>. Ratings are stored in the <code>xmp:Rating</code> field of the XMP metadata — a standard field supported by Lightroom, Capture One, Adobe Bridge, FastRawViewer, and most other photo software.</p><h3 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h3><p>The shortcut can be changed under <strong>Rating / Label Key</strong> in Settings:</p><table tabindex="0"><thead><tr><th>Option</th><th>Shortcut</th></tr></thead><tbody><tr><td>Number key</td><td><code>0</code>–<code>9</code></td></tr><tr><td>⌘ + number</td><td><code>⌘0</code>–<code>⌘9</code></td></tr><tr><td>^ + number</td><td><code>^0</code>–<code>^9</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Key</th><th>Rating</th></tr></thead><tbody><tr><td><code>0</code></td><td>No rating</td></tr><tr><td><code>1</code></td><td>★☆☆☆☆</td></tr><tr><td><code>2</code></td><td>★★☆☆☆</td></tr><tr><td><code>3</code></td><td>★★★☆☆</td></tr><tr><td><code>4</code></td><td>★★★★☆</td></tr><tr><td><code>5</code></td><td>★★★★★</td></tr></tbody></table><h3 id="right-click-menu" tabindex="-1">Right-click menu <a class="header-anchor" href="#right-click-menu" aria-label="Permalink to &quot;Right-click menu&quot;">​</a></h3><p>Right-click a thumbnail → <strong>Rating</strong> to apply the same ratings without leaving the mouse. Useful when working keyboard-free.</p><h2 id="rating-grouped-photos" tabindex="-1">Rating grouped photos <a class="header-anchor" href="#rating-grouped-photos" aria-label="Permalink to &quot;Rating grouped photos&quot;">​</a></h2><p>When you rate a grouped photo (e.g. a burst sequence), the rating <strong>propagates to every shot in the group</strong> by default. To adjust the rating for individual shots, use the metadata bar.</p><p>See <a href="./rating-spec.html">Rating propagation</a> for full details on how this works and how to adjust individual shots.</p><h2 id="color-labels" tabindex="-1">Color labels <a class="header-anchor" href="#color-labels" aria-label="Permalink to &quot;Color labels&quot;">​</a></h2><p>Label data is written to <code>xmp:Label</code> and <code>photoshop:LabelColor</code> (Adobe Bridge compatible). Color labels can be set via <strong>keyboard shortcut</strong> or <strong>right-click menu</strong>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Label</th></tr></thead><tbody><tr><td><code>6</code></td><td>Red</td></tr><tr><td><code>7</code></td><td>Yellow</td></tr><tr><td><code>8</code></td><td>Green</td></tr><tr><td><code>9</code></td><td>Blue</td></tr><tr><td>—</td><td>Purple (no shortcut assigned)</td></tr></tbody></table><p>Purple can be applied from the right-click menu or the metadata bar.</p><h2 id="where-xmp-is-saved" tabindex="-1">Where XMP is saved <a class="header-anchor" href="#where-xmp-is-saved" aria-label="Permalink to &quot;Where XMP is saved&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File type</th><th>Default</th><th>Option</th></tr></thead><tbody><tr><td>JPEG</td><td>Embedded directly in the file</td><td>Sidecar (<code>.xmp</code>) — changeable in Settings</td></tr><tr><td>RAW (<code>.arw</code>, <code>.cr3</code>, etc.)</td><td>Sidecar <code>.xmp</code> file with the same stem name</td><td>—</td></tr></tbody></table><h2 id="carrying-ratings-into-lightroom" tabindex="-1">Carrying ratings into Lightroom <a class="header-anchor" href="#carrying-ratings-into-lightroom" aria-label="Permalink to &quot;Carrying ratings into Lightroom&quot;">​</a></h2><p>After rating in bridge-lite, open the same folder in Lightroom. Ratings appear automatically when XMP auto-read is enabled.</p>',21)])])}const b=e(d,[["render",i]]);export{p as __pageData,b as default};
